from pathlib import Path

root=Path('apps/painel-ldr/src')

# 1) Expand curriculum from 90 to 180 distinct learning units without duplicating lesson titles.
p=root/'content/psychoanalysis-curriculum.ts'
s=p.read_text(encoding='utf-8')
if 'const basePsychoanalysisModules' not in s:
    s=s.replace('export const psychoanalysisModules:PsychoanalysisModule[]=[','const basePsychoanalysisModules:PsychoanalysisModule[]=[',1)
    marker='\nexport const PSYCHOANALYSIS_TOTAL_LESSONS=psychoanalysisModules.reduce((n,m)=>n+m.lessons.length,0);'
    addition='''\nconst extensionTitles:Record<number,string[]>={\n1:["Leitura orientada: Estudos sobre a Histeria","Mapa conceitual da Primeira Tópica","Exercício: consciente, pré-consciente e inconsciente","Caso histórico: o método catártico","Prática de leitura: Associação Livre","Perguntas de revisão do Módulo 1","Conexões entre sintoma, memória e afeto","Diário de estudo: o nascimento do método","Preparação para a atividade final"],\n2:["Leitura orientada: O Ego e o Id","Mapa conceitual: Id, Ego e Superego","Exercício sobre conflito psíquico","Princípio do prazer na vida cotidiana","Princípio da realidade e mediação","Ideal do Eu e exigência moral","Perguntas de revisão da Segunda Tópica","Aplicação teórica em situação hipotética","Preparação para a atividade final"],\n3:["Leitura orientada: Três Ensaios","Mapa das fases do desenvolvimento","Exercício: fase oral e dependência","Exercício: fase anal e controle","Exercício: fase fálica e diferença","Latência e reorganização psíquica","Complexo de Édipo em perspectiva histórica","Perguntas de revisão do desenvolvimento","Preparação para a atividade final"],\n4:["Leitura orientada: Introdução ao Narcisismo","Mapa conceitual das pulsões","Fonte, pressão, meta e objeto na prática teórica","Eros e ligação psíquica","Compulsão à repetição e pulsão de morte","Narcisismo primário e secundário","Investimento libidinal e relações","Perguntas de revisão das pulsões","Preparação para a atividade final"],\n5:["Leitura orientada: A Repressão","Mapa das defesas do Ego","Exercício comparativo: recalque e negação","Projeção sem rótulos diagnósticos","Sublimação e produção cultural","Racionalização e narrativa consciente","Formação reativa em perspectiva teórica","Perguntas de revisão das defesas","Preparação para a atividade final"],\n6:["Leitura orientada: A Interpretação dos Sonhos","Mapa do trabalho do sonho","Exercício: manifesto e latente","Condensação e deslocamento","Atos falhos no cotidiano","Esquecimento e conflito","Chistes e economia psíquica","Perguntas de revisão das formações do inconsciente","Preparação para a atividade final"],\n7:["Leitura orientada: Recomendações aos Médicos","Mapa da técnica psicanalítica","Associação Livre em profundidade","Atenção Flutuante e escuta","Enquadre e constância","Silêncio, tempo e intervenção","Resistência sem confronto mecânico","Perguntas de revisão da técnica","Preparação para a atividade final"],\n8:["Leitura orientada: A Dinâmica da Transferência","Mapa da transferência","Repetição e atualização na relação analítica","Transferência amorosa e manejo","Transferência hostil e resistência","Contratransferência e elaboração","Limites éticos na relação analítica","Perguntas de revisão da transferência","Preparação para a atividade final"],\n9:["Leitura orientada: Melanie Klein","Leitura orientada: Donald Winnicott","Leitura orientada: Jacques Lacan","Mapa comparativo pós-freudiano","Klein e fantasia inconsciente","Winnicott e ambiente facilitador","Lacan, linguagem e sujeito","Perguntas de revisão dos autores","Preparação para a atividade final"],\n10:["Leitura orientada: O Mal-Estar na Civilização","Mapa do sujeito e da cultura","Ansiedade e contemporaneidade sem diagnóstico automático","Trabalho, produtividade e esgotamento","Redes sociais e reconhecimento","Imediatismo e satisfação","Vazio, repetição e laço social","Perguntas de revisão da Psicanálise aplicada","Síntese final do percurso"]\n};\nfunction extensionLesson(module:PsychoanalysisModule,title:string,index:number):PsychoanalysisLesson{return {id:`m${module.id}-l${10+index}`,title,summary:module.focus,content:[`Esta unidade aprofunda ${title.toLowerCase()} dentro do eixo do módulo ${module.id}.`,`O objetivo é transformar a leitura em elaboração: compare conceitos, registre dúvidas e relacione esta unidade aos textos originais recomendados no módulo.`,`Ao final, produza uma síntese curta com o que mudou na sua compreensão do tema e uma pergunta que você levaria para um encontro ao vivo ou para o fórum da formação.`]};}\nexport const psychoanalysisModules:PsychoanalysisModule[]=basePsychoanalysisModules.map(module=>({...module,lessons:[...module.lessons,...((extensionTitles[module.id]??[]).map((title,index)=>extensionLesson(module,title,index)))]}));\n'''
    if marker not in s: raise SystemExit('curriculum marker not found')
    s=s.replace(marker,addition+marker,1)
p.write_text(s,encoding='utf-8')

# 2) Student experience: mobile-safe module list, forum, one-new-lesson-per-day guidance, cohort/certificate messaging.
