for old,new in [('90 aulas','180 unidades de aprendizagem'),('Aulas, textos, materiais e gravações disponibilizadas permanecem','Textos, materiais, atividades e conteúdos disponibilizados permanecem'),('aulas gravadas, textos, materiais e gravações disponibilizadas','conteúdos digitais, textos, materiais e recursos disponibilizados'),('aulas gravadas','conteúdos digitais')]: s=s.replace(old,new)
